import { createEffect, on } from "solid-js";

import { InputEngineEvent, NavigateInputEvent, NavigateInputEventName } from "#core/ui/input/input-support.js";
import { IsControllerActive } from "#core/ui-next/services/input.js";

/**
 * A simple controller focus navigation service for use on in sandboxes
 */
export class SandboxNavigation {
	private targetElement: HTMLElement | undefined;

	constructor() {
		engine.on("InputAction", this.onEngineInput.bind(this));

		createEffect(
			on(IsControllerActive, (isControllerActive: boolean) => {
				if (isControllerActive) {
					this.targetElement?.focus();
				} else {
					(document.activeElement as HTMLElement)?.blur();
				}
			}),
		);
	}

	setFocus(element: HTMLElement) {
		this.targetElement = element;
	}

	onEngineInput(name: string, status: InputActionStatuses, x: number, y: number) {
		if (name.startsWith("nav-")) {
			let navigationDirection: InputNavigationAction = InputNavigationAction.NONE;
			switch (name) {
				case "nav-up":
					navigationDirection = InputNavigationAction.UP;
					break;
				case "nav-down":
					navigationDirection = InputNavigationAction.DOWN;
					break;
				case "nav-left":
					navigationDirection = InputNavigationAction.LEFT;
					break;
				case "nav-right":
					navigationDirection = InputNavigationAction.RIGHT;
					break;
				case "nav-next":
					navigationDirection = InputNavigationAction.NEXT;
					break;
				case "nav-previous":
					navigationDirection = InputNavigationAction.PREVIOUS;
					break;
				case "nav-shell-next":
					navigationDirection = InputNavigationAction.SHELL_NEXT;
					break;
				case "nav-shell-previous":
					navigationDirection = InputNavigationAction.SHELL_PREVIOUS;
					break;
			}

			const navigationEvent = new NavigateInputEvent(NavigateInputEventName, {
				bubbles: true,
				cancelable: true,
				detail: { name: name, status: status, x: x, y: y, navigation: navigationDirection },
			});

			this.targetElement?.dispatchEvent(navigationEvent);
		} else {
			const isTouch: boolean = name.substr(0, 6) == "touch-";
			const isMouse: boolean = name.substr(0, 12) == "mousebutton-" || name.substr(0, 11) == "mousewheel-";
			const inputEvent = new InputEngineEvent(name, status, x, y, isTouch, isMouse);

			if (document.activeElement?.hasAttribute("data-activatable")) {
				document.activeElement.dispatchEvent(inputEvent);
			}
		}
	}
}
